import type { Code, Exercise } from "./types";
import { curriculumKCs } from "./curriculum-data";
import { CURRICULUM_VERSION } from "./curriculum";
type Spec={kc:string;title:string;instruction:string;starter?:Partial<Code>;solution:Partial<Code>;tests:[string,string][];hints?:string[]};
const specs:Spec[]=[];
function add(kc:string,title:string,instruction:string,starter:Partial<Code>,solution:Partial<Code>,tests:[string,string][],hints?:string[]){specs.push({kc,title,instruction,starter,solution,tests,hints});}
const tag=(name:string)=>`sourceFacts.html.tags.${name}`;
const doc=(title:string,body:string)=>`<!doctype html><html lang="id"><head><meta charset="utf-8"><title>${title}</title></head><body>${body}</body></html>`;

// JS01: complete source documents; source parsing sees what the preview sanitizer removes.
for(const [title,body,required] of [
 ["SIMPUS-Mini","<h1>SIMPUS-Mini</h1><p>Katalog perpustakaan</p>","h1"],
 ["Katalog Buku","<h1>Katalog Buku</h1><table><tbody><tr><td>Web</td></tr></tbody></table>","table"],
 ["Pendaftaran Anggota","<h1>Pendaftaran Anggota</h1><form><label for=nama>Nama</label><input id=nama name=nama></form>","form"],
] as const)add("H01",`Dokumen ${title}`,`Tulis dokumen HTML lengkap berbahasa Indonesia dengan doctype HTML, head/body eksplisit dan tertutup, charset UTF-8, title ${title}, heading utama serta ${required==='table'?'tabel katalog':required==='form'?'form anggota berlabel':'paragraf pengantar'}.`,{html:"<!-- Susun dokumen lengkap, bukan hanya body -->"},{html:doc(title,body)},[
 ["Sumber dokumen eksplisit dan tanpa parse error",`${tag('html')}?.length===1 && ['html','head','body'].every(n=>sourceFacts.html.tags[n]?.[0]?.explicit && sourceFacts.html.tags[n]?.[0]?.closed) && sourceFacts.html.doctype==='html' && sourceFacts.html.errors.length===0`],
 ["Metadata milik mahasiswa berada pada head",`${tag('html')}[0].attrs.lang==='id' && ${tag('title')}?.[0]?.parent==='head' && ${tag('title')}[0].text===${JSON.stringify(title)} && ${tag('meta')}?.some(n=>n.parent==='head' && n.attrs.charset?.toLowerCase()==='utf-8')`],
 ["Konten berada pada body",`${tag('h1')}?.[0]?.parent==='body' && ${tag('h1')}[0].text===${JSON.stringify(title)} && !!sourceFacts.html.tags.${required}`],
 ],["Bedakan metadata head dan konten body.","Tulis doctype dan html lang=id, lalu head serta body secara eksplisit.","Contoh metadata: <head><meta charset=\"utf-8\"><title>Judul halaman</title></head>"]);

add("H02","Landmark beranda","Buat satu header dengan nav aria-label='Navigasi utama', satu main dengan h1 SIMPUS-Mini dan section berjudul h2 Statistik, lalu footer. Gunakan elemen sesuai maknanya.",{}, {html:'<header><nav aria-label="Navigasi utama"><a href="index.html">Beranda</a></nav></header><main><h1>SIMPUS-Mini</h1><section><h2>Statistik</h2><p>Data perpustakaan</p></section></main><footer>Perpustakaan</footer>'},[
 ["Landmark tidak berulang","['header','main','footer'].every(s=>document.querySelectorAll(s).length===1)"],
 ["Hierarki dan nama navigasi","!!document.querySelector('header nav[aria-label="+JSON.stringify('Navigasi utama')+"]') && !!document.querySelector('main > h1') && !!document.querySelector('main section > h2')"],
 ["Tautan berada pada navigasi","document.querySelector('header nav a')?.getAttribute('href')==='index.html' && !document.querySelector('main h3')"]]);
add("H02","Form anggota yang berlabel","Perbaiki form: setiap input memiliki label for yang benar, field bantuan #bantuan dihubungkan ke input no_anggota dengan aria-describedby, tombol submit memiliki teks bermakna.",{html:'<form><input id="nama" name="nama"><input id="no_anggota" name="no_anggota"><p id="bantuan">Contoh A001</p><button type="submit"></button></form>'},{html:'<form><label for="nama">Nama</label><input id="nama" name="nama"><label for="no_anggota">Nomor anggota</label><input id="no_anggota" name="no_anggota" aria-describedby="bantuan"><p id="bantuan">Contoh A001</p><button type="submit">Simpan anggota</button></form>'},[
 ["Semua kontrol mempunyai nama dari label","['nama','no_anggota'].every(id=>document.querySelector('label[for='+id+']')?.textContent.trim().length>0)"],
 ["Bantuan terhubung ke kontrol","document.querySelector('#no_anggota')?.getAttribute('aria-describedby')==='bantuan' && !!document.querySelector('#bantuan')"],
 ["Aksi dapat dipahami","document.querySelector('button[type=submit]')?.textContent.trim().length>5"]]);
add("H02","Hierarki katalog","Susun main dengan satu h1 Katalog, dua section (Buku dan Anggota) berjudul h2, dan nav berlabel Navigasi katalog. Tautan menuju bagian dengan id buku/anggota.",{}, {html:'<nav aria-label="Navigasi katalog"><a href="#buku">Buku</a><a href="#anggota">Anggota</a></nav><main><h1>Katalog</h1><section id="buku"><h2>Buku</h2></section><section id="anggota"><h2>Anggota</h2></section></main>'},[
 ["Satu heading utama","document.querySelectorAll('h1').length===1 && document.querySelector('main > h1')?.textContent==='Katalog'"],
 ["Bagian berjudul sesuai hierarki","['buku','anggota'].every(id=>!!document.querySelector('main section#'+id+' > h2')) && !document.querySelector('h3')"],
 ["Navigasi merujuk bagian yang ada",`!!document.querySelector('nav[aria-label="Navigasi katalog"]') && ['buku','anggota'].every(id=>!!document.querySelector('nav a[href="#'+id+'"]') && !!document.getElementById(id))`]]);

for(const [title,base,links] of [
 ["Menu beranda","https://fixture.invalid/simpus/index.html",[["Buku","buku/list.html"],["Anggota","anggota/list.html"]]],
 ["Menu halaman buku","https://fixture.invalid/simpus/buku/list.html",[["Beranda","../index.html"],["Anggota","../anggota/list.html"]]],
 ["Kembali dari form anggota","https://fixture.invalid/simpus/anggota/tambah.html",[["Daftar Anggota","list.html"],["Beranda","../index.html"]]],
] as const)add("H03",title,`Anda mengedit ${base.split('/simpus/')[1]}. Buat h1 ${title} dan nav dengan tautan ${links.map(([label,path])=>label+' menuju '+path).join(', ')}. Gunakan path relatif agar tetap berjalan di subfolder /simpus/.`,{}, {html:`<h1>${title}</h1><nav>${links.map(([label,path])=>`<a href="${path}">${label}</a>`).join('')}</nav>`},[
 ["Tujuan relatif benar",`(()=>{const expected=${JSON.stringify(links)};return expected.every(([label,path])=>{const a=[...document.querySelectorAll('nav a')].find(a=>a.textContent===label);return a && new URL(a.getAttribute('href'),${JSON.stringify(base)}).href===new URL(path,${JSON.stringify(base)}).href;});})()`],
 ["Path tidak terikat root/mesin","[...document.querySelectorAll('nav a')].length===2 && [...document.querySelectorAll('nav a')].every(a=>!a.getAttribute('href').startsWith('/') && !a.getAttribute('href').includes(':'))"],
 ["Heading dan teks tidak kosong",`document.querySelector('h1')?.textContent===${JSON.stringify(title)} && [...document.querySelectorAll('nav a')].every(a=>a.textContent.trim().length>0)`]]);

for(const [title,headers,data] of [
 ["Katalog buku",["Judul","Stok"],[["HTML Dasar","2"],["CSS Praktis","0"],["JavaScript","5"]]],
 ["Daftar anggota",["Nomor","Nama","Telepon"],[["A001","Dina","08123"],["A002","Budi","08234"]]],
 ["Riwayat peminjaman",["Anggota","Buku","Status"],[["Dina","HTML Dasar","dipinjam"],["Budi","CSS Praktis","dikembalikan"]]],
] as const)add("H04",title,`Buat table id=daftar, caption ${title}, thead dengan th scope=col ${headers.join(', ')}, serta tbody berisi data ${JSON.stringify(data)}. Setiap data harus tetap berpasangan dengan kolomnya.`,{}, {html:`<table id="daftar"><caption>${title}</caption><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${data.map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table>`},[
 ["Header sesuai urutan",`JSON.stringify([...document.querySelectorAll('#daftar thead th')].map(n=>n.textContent))===${JSON.stringify(JSON.stringify(headers))}`],
 ["Baris memiliki pasangan data benar",`JSON.stringify([...document.querySelectorAll('#daftar tbody tr')].map(row=>[...row.querySelectorAll('td')].map(n=>n.textContent)))===${JSON.stringify(JSON.stringify(data))}`],
 ["Semantik tabel dan cakupan header",`document.querySelector('#daftar caption')?.textContent===${JSON.stringify(title)} && [...document.querySelectorAll('#daftar th')].every(n=>n.getAttribute('scope')==='col')`]]);

add("H05","Form stok buku","Buat form #buku method=post action=proses_tambah.php; input judul required, input stok type=number min=0 step=1 required dan label masing-masing. Sediakan button type=submit.",{}, {html:'<form id="buku" method="post" action="proses_tambah.php"><label for="judul">Judul</label><input id="judul" name="judul" required><label for="stok">Stok</label><input id="stok" name="stok" type="number" min="0" step="1" required><button type="submit">Simpan</button></form>'},[
 ["Kontrak pengiriman dan label","document.querySelector('#buku')?.getAttribute('method')==='post' && document.querySelector('#buku')?.getAttribute('action')==='proses_tambah.php' && ['judul','stok'].every(id=>!!document.querySelector('label[for='+id+']'))"],
 ["Kosong/negatif ditolak, nol diterima","(()=>{const s=document.querySelector('input[name=stok]');if(!s||s.type!=='number')return false;s.value='';const a=!s.checkValidity();s.value='-1';const b=!s.checkValidity();s.value='0';return a&&b&&s.checkValidity();})()"],
 ["Judul wajib dan tombol sesuai","document.querySelector('[name=judul]')?.required===true && !!document.querySelector('button[type=submit]')"]]);
add("H05","Identitas anggota","Buat form dengan label/input nama required dan no_anggota type=text required maxlength=20. Nomor A001 harus dapat diterima. Tambahkan tombol submit.",{}, {html:'<form><label for="nama">Nama</label><input id="nama" name="nama" required><label for="no_anggota">Nomor</label><input id="no_anggota" name="no_anggota" type="text" required maxlength="20"><button type="submit">Simpan</button></form>'},[
 ["Nama kosong tidak valid","(()=>{const n=document.querySelector('[name=nama]');if(!n)return false;n.value='';return !n.checkValidity();})()"],
 ["Nomor alfanumerik dipertahankan","(()=>{const n=document.querySelector('[name=no_anggota]');if(!n||n.type!=='text')return false;n.value='A001';return n.value==='A001'&&n.checkValidity()&&n.maxLength===20;})()"],
 ["Label dan aksi terhubung","['nama','no_anggota'].every(id=>!!document.querySelector('label[for='+id+']')&&!!document.getElementById(id)) && !!document.querySelector('button[type=submit]')"]]);
add("H05","Tahun dan kategori","Buat form dengan tahun type=number required min=1900 max=2026 step=1 dan select kategori required (pilihan kosong, Web, Umum). Setiap kontrol berlabel.",{}, {html:'<form><label for="tahun">Tahun</label><input id="tahun" name="tahun" type="number" required min="1900" max="2026" step="1"><label for="kategori">Kategori</label><select id="kategori" name="kategori" required><option value="">Pilih</option><option value="Web">Web</option><option value="Umum">Umum</option></select><button type="submit">Simpan</button></form>'},[
 ["Rentang tahun diuji di kedua batas","(()=>{const t=document.querySelector('[name=tahun]');return t&&t.type==='number'&&[[1899,false],[1900,true],[2026,true],[2027,false]].every(([n,ok])=>{t.value=n;return t.checkValidity()===ok;});})()"],
 ["Pilihan kosong ditolak","(()=>{const s=document.querySelector('select[name=kategori]');if(!s)return false;s.value='';const bad=!s.checkValidity();s.value='Web';return bad&&s.checkValidity()&&s.value==='Web'&&[...s.options].some(o=>o.value==='Umum');})()"],
 ["Kontrol memiliki label","['tahun','kategori'].every(id=>!!document.querySelector('label[for='+id+']')&&!!document.getElementById(id))"]]);

// CSS tasks have fixed HTML fixtures. JS must remain empty to measure native styling.
const cssTask=(kc:string,title:string,instruction:string,html:string,css:string,tests:[string,string][])=>add(kc,title,instruction,{html},{css},tests,["Amati elemen induk dan anak pada HTML fixture.","Periksa selector dan properti di materi KC; jangan menyelesaikan tugas CSS dengan JavaScript.",css.split('}')[0]+'}']);
cssTask("C01","Konflik link navbar","Link umum merah, tetapi link di header nav harus rgb(29,91,138). Gunakan aturan yang lebih spesifik tanpa !important.",'<header><nav><a id="menu">Buku</a></nav></header><main><a id="umum">Bantuan</a></main>','header nav a{color:rgb(29,91,138)} a{color:rgb(200,0,0)}',[
 ["Navbar menang dalam konflik","getComputedStyle(document.querySelector('#menu')).color==='rgb(29, 91, 138)'"],["Link lain tetap merah","getComputedStyle(document.querySelector('#umum')).color==='rgb(200, 0, 0)'"],["Tidak memakai important","[...document.styleSheets].every(s=>[...s.cssRules].every(r=>!r.cssText.includes('!important')))"]]);
cssTask("C01","Selektor atribut aksi","Warnai hanya button[data-action=hapus] merah rgb(180,0,0); tombol lain berwarna rgb(0,80,0).",'<button data-action="hapus">Hapus</button><button data-action="edit">Edit</button><button>Detail</button>','button{color:rgb(0,80,0)}button[data-action="hapus"]{color:rgb(180,0,0)}',[
 ["Hapus berbeda","getComputedStyle(document.querySelector('[data-action=hapus]')).color==='rgb(180, 0, 0)'"],["Aksi lain tetap hijau","[...document.querySelectorAll('button:not([data-action=hapus])')].every(n=>getComputedStyle(n).color==='rgb(0, 80, 0)')"],["Elemen baru mengikuti selector","(()=>{const n=document.createElement('button');n.dataset.action='hapus';document.body.append(n);return getComputedStyle(n).color==='rgb(180, 0, 0)';})()"]]);
cssTask("C01","Pseudo-class baris genap","Gunakan nth-child(even) agar baris genap background rgb(230,240,250) dan baris ganjil putih.",'<table><tbody><tr><td>A</td></tr><tr><td>B</td></tr><tr><td>C</td></tr></tbody></table>','tbody tr{background:rgb(255,255,255)}tbody tr:nth-child(even){background:rgb(230,240,250)}',[
 ["Baris ganjil putih","getComputedStyle(document.querySelector('tbody tr')).backgroundColor==='rgb(255, 255, 255)'"],["Baris genap berwarna","getComputedStyle(document.querySelectorAll('tr')[1]).backgroundColor==='rgb(230, 240, 250)'"],["Baris dinamis ikut pola","(()=>{document.querySelector('tbody').insertAdjacentHTML('beforeend','<tr><td>D</td></tr>');return getComputedStyle(document.querySelectorAll('tr')[3]).backgroundColor==='rgb(230, 240, 250)';})()"]]);

cssTask("C02","Lebar total kartu",".card harus memiliki total lebar 240px, padding 20px dan border 2px. Gunakan border-box.",'<div class="card">Total buku</div>','.card{box-sizing:border-box;width:240px;padding:20px;border:2px solid black}',[
 ["Ukuran total benar","Math.abs(document.querySelector('.card').getBoundingClientRect().width-240)<1"],["Padding dan border","getComputedStyle(document.querySelector('.card')).paddingLeft==='20px'&&getComputedStyle(document.querySelector('.card')).borderLeftWidth==='2px'"],["Border box eksplisit","getComputedStyle(document.querySelector('.card')).boxSizing==='border-box'"]]);
cssTask("C02","Konten terpusat","Di fixture 500px, batasi main ke 300px dan pusatkan dengan margin horizontal auto. Padding main 16px termasuk dalam lebar.",'<div class="fixture" style="width:500px"><main>Katalog</main></div>','main{box-sizing:border-box;max-width:300px;padding:16px;margin:0 auto}',[
 ["Lebar dibatasi","Math.abs(document.querySelector('main').getBoundingClientRect().width-300)<1"],["Terpusat","(()=>{const p=document.querySelector('.fixture').getBoundingClientRect(),n=document.querySelector('main').getBoundingClientRect();return Math.abs((n.left-p.left)-(p.right-n.right))<1;})()"],["Padding termasuk ukuran","getComputedStyle(document.querySelector('main')).paddingLeft==='16px'&&getComputedStyle(document.querySelector('main')).boxSizing==='border-box'"]]);
cssTask("C02","Reset dan pewarisan","Terapkan border-box ke semua elemen, .panel font-size 18px line-height 27px, dan paragraf tanpa margin bawaan.",'<section class="panel"><p>Perpustakaan</p><div style="width:100px;padding:10px;border:1px solid">Data</div></section>','*{box-sizing:border-box}.panel{font-size:18px;line-height:27px}.panel p{margin:0}',[
 ["Font diwariskan","getComputedStyle(document.querySelector('p')).fontSize==='18px'&&getComputedStyle(document.querySelector('p')).lineHeight==='27px'"],["Margin reset","getComputedStyle(document.querySelector('p')).marginTop==='0px'&&getComputedStyle(document.querySelector('p')).marginBottom==='0px'"],["Ukuran anak tidak bertambah","Math.abs(document.querySelector('.panel div').getBoundingClientRect().width-100)<1"]]);

cssTask("C03","Navbar dua sisi","Atur .nav display flex, justify-content space-between, align-items center, gap 16px.",'<nav class="nav"><strong>SIMPUS</strong><a>Buku</a><a>Anggota</a></nav>','.nav{display:flex;justify-content:space-between;align-items:center;gap:16px}',[
 ["Flex aktif","getComputedStyle(document.querySelector('.nav')).display==='flex'"],["Distribusi dan sumbu silang","getComputedStyle(document.querySelector('.nav')).justifyContent==='space-between'&&getComputedStyle(document.querySelector('.nav')).alignItems==='center'"],["Gap konsisten","getComputedStyle(document.querySelector('.nav')).gap==='16px'"]]);
cssTask("C03","Menu yang membungkus",".nav lebarnya 220px. Buat flex-wrap wrap, gap 10px dan anak berlebar 100px tanpa menyusut.",'<nav class="nav" style="width:220px"><a>Buku</a><a>Anggota</a><a>Peminjaman</a></nav>','.nav{display:flex;flex-wrap:wrap;gap:10px}.nav a{flex:0 0 100px}',[
 ["Wrap diaktifkan","getComputedStyle(document.querySelector('.nav')).display==='flex'&&getComputedStyle(document.querySelector('.nav')).flexWrap==='wrap'"],["Dua item pertama sejajar","Math.abs(document.querySelectorAll('a')[0].getBoundingClientRect().top-document.querySelectorAll('a')[1].getBoundingClientRect().top)<1"],["Item ketiga pindah baris","document.querySelectorAll('a')[2].getBoundingClientRect().top>document.querySelectorAll('a')[0].getBoundingClientRect().top"]]);
cssTask("C03","Aksi form vertikal","Buat .actions flex column dengan gap 12px dan align-items stretch. Tombol memenuhi lebar kontainer 260px.",'<div class="actions" style="width:260px"><button>Simpan</button><button>Batal</button></div>','.actions{display:flex;flex-direction:column;gap:12px;align-items:stretch}',[
 ["Sumbu vertikal","getComputedStyle(document.querySelector('.actions')).display==='flex'&&getComputedStyle(document.querySelector('.actions')).flexDirection==='column'"],["Kontrol melebar","[...document.querySelectorAll('button')].every(n=>Math.abs(n.getBoundingClientRect().width-260)<1)"],["Jarak nyata antarkontrol","Math.abs(document.querySelectorAll('button')[1].getBoundingClientRect().top-document.querySelectorAll('button')[0].getBoundingClientRect().bottom-12)<1"]]);

cssTask("C04","Tiga kartu statistik",".stats display grid dengan tiga kolom sama besar dan gap 12px pada kontainer 360px.",'<div class="stats" style="width:360px"><article>Buku</article><article>Anggota</article><article>Dipinjam</article></div>','.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}',[
 ["Grid tiga kolom","getComputedStyle(document.querySelector('.stats')).display==='grid'&&getComputedStyle(document.querySelector('.stats')).gridTemplateColumns.split(' ').length===3"],["Kolom sama besar","[...document.querySelectorAll('article')].every(n=>Math.abs(n.getBoundingClientRect().width-112)<1)"],["Item keempat baris baru","(()=>{const n=document.createElement('article');n.textContent='Terlambat';document.querySelector('.stats').append(n);return n.getBoundingClientRect().top>document.querySelector('article').getBoundingClientRect().top;})()"]]);
cssTask("C04","Panel dua kolom","Buat .layout grid kolom 120px dan sisa ruang (1fr), gap 20px pada kontainer 400px.",'<div class="layout" style="width:400px"><aside>Menu</aside><section>Katalog</section></div>','.layout{display:grid;grid-template-columns:120px 1fr;gap:20px}',[
 ["Grid aktif","getComputedStyle(document.querySelector('.layout')).display==='grid'"],["Sidebar tetap","Math.abs(document.querySelector('aside').getBoundingClientRect().width-120)<1"],["Kolom utama mendapat sisa ruang","Math.abs(document.querySelector('section').getBoundingClientRect().width-260)<1"]]);
cssTask("C04","Galeri buku dua baris","Buat grid dua kolom 100px, row-gap 16px dan column-gap 8px untuk empat kartu.",'<div class="books"><article>A</article><article>B</article><article>C</article><article>D</article></div>','.books{display:grid;grid-template-columns:100px 100px;row-gap:16px;column-gap:8px}',[
 ["Kolom tetap","getComputedStyle(document.querySelector('.books')).gridTemplateColumns==='100px 100px'"],["Jarak kolom","Math.abs(document.querySelectorAll('article')[1].getBoundingClientRect().left-document.querySelectorAll('article')[0].getBoundingClientRect().right-8)<1"],["Jarak baris","Math.abs(document.querySelectorAll('article')[2].getBoundingClientRect().top-document.querySelectorAll('article')[0].getBoundingClientRect().bottom-16)<1"]]);

cssTask("C05","Tabel katalog terbaca","Atur table border-collapse collapse dan semua th/td padding 12px border 1px solid rgb(120,120,120).",'<table><thead><tr><th>Judul</th><th>Stok</th></tr></thead><tbody><tr><td>Web</td><td>2</td></tr></tbody></table>','table{border-collapse:collapse}th,td{padding:12px;border:1px solid rgb(120,120,120)}',[
 ["Border digabung","getComputedStyle(document.querySelector('table')).borderCollapse==='collapse'"],["Semua sel memiliki padding","[...document.querySelectorAll('th,td')].every(n=>getComputedStyle(n).paddingTop==='12px')"],["Border semua sel","[...document.querySelectorAll('th,td')].every(n=>getComputedStyle(n).borderLeftWidth==='1px'&&getComputedStyle(n).borderLeftStyle==='solid')"]]);
cssTask("C05","Zebra anggota","Beri tbody tr background putih, baris genap rgb(230,240,250). th tetap rgb(29,91,138).",'<table><thead><tr><th>Anggota</th></tr></thead><tbody><tr><td>Dina</td></tr><tr><td>Budi</td></tr><tr><td>Sari</td></tr></tbody></table>','tbody tr{background:white}tbody tr:nth-child(even){background:rgb(230,240,250)}th{background:rgb(29,91,138)}',[
 ["Header terpisah","getComputedStyle(document.querySelector('th')).backgroundColor==='rgb(29, 91, 138)'"],["Genap berwarna","getComputedStyle(document.querySelectorAll('tbody tr')[1]).backgroundColor==='rgb(230, 240, 250)'"],["Ganjil tetap putih","getComputedStyle(document.querySelector('tbody tr')).backgroundColor==='rgb(255, 255, 255)'"]]);
cssTask("C05","Warna aksi berdasarkan makna","Beri .edit warna rgb(0,90,0), .hapus rgb(180,0,0), .detail rgb(0,0,160) tanpa bergantung posisi tombol.",'<table><tbody><tr><td><button class="edit">Edit</button><button class="detail">Detail</button><button class="hapus">Hapus</button></td></tr></tbody></table>','.edit{color:rgb(0,90,0)}.hapus{color:rgb(180,0,0)}.detail{color:rgb(0,0,160)}',[
 ["Edit dan hapus berbeda","getComputedStyle(document.querySelector('.edit')).color==='rgb(0, 90, 0)'&&getComputedStyle(document.querySelector('.hapus')).color==='rgb(180, 0, 0)'"],["Detail bermakna sendiri","getComputedStyle(document.querySelector('.detail')).color==='rgb(0, 0, 160)'"],["Urutan diubah tetap benar","(()=>{const td=document.querySelector('td');td.prepend(document.querySelector('.hapus'));return getComputedStyle(document.querySelector('.hapus')).color==='rgb(180, 0, 0)'&&getComputedStyle(document.querySelector('.edit')).color==='rgb(0, 90, 0)';})()"]]);

