const jsTask=(kc:string,title:string,instruction:string,js:string,tests:[string,string][],html='')=>add(kc,title,instruction,{html,js:'// Definisikan fungsi window sesuai kontrak soal.'},{js},tests,["Perhatikan tipe input dan nilai kembalian yang diminta.","Uji data kosong dan batas; jangan menetapkan hasil untuk satu contoh saja.",js.slice(0,Math.min(100,js.indexOf('{')+1||60))+' /* lengkapi solusi */']);
jsTask('J01','Nilai persediaan','Definisikan window.nilaiStok(stok,harga): hasil perkalian dua angka nonnegatif. Input negatif/nonangka mengembalikan null. Jangan mengubah input.','window.nilaiStok=(stok,harga)=>typeof stok===\'number\'&&typeof harga===\'number\'&&Number.isFinite(stok)&&Number.isFinite(harga)&&stok>=0&&harga>=0?stok*harga:null;',[
 ['Beragam data normal','[[2,10000,20000],[7,3500,24500],[1,125,125]].every(([a,b,v])=>window.nilaiStok(a,b)===v)'],['Nol adalah nilai sah','window.nilaiStok(0,100)===0&&window.nilaiStok(8,0)===0'],['Input invalid ditolak',"window.nilaiStok(-1,3)===null&&window.nilaiStok('2',3)===null&&window.nilaiStok(NaN,3)===null"]]);
jsTask('J01','Sisa buku','Definisikan window.sisaBuku(stok,dipinjam) untuk dua integer nonnegatif; hasil stok-dipinjam. Jika dipinjam melebihi stok atau input tidak sah, kembalikan null.','window.sisaBuku=(s,p)=>Number.isInteger(s)&&Number.isInteger(p)&&s>=0&&p>=0&&p<=s?s-p:null;',[
 ['Pengurangan bervariasi','window.sisaBuku(9,2)===7&&window.sisaBuku(15,8)===7&&window.sisaBuku(5,1)===4'],['Stok habis/nol','window.sisaBuku(3,3)===0&&window.sisaBuku(0,0)===0'],['Tidak meminjam stok invalid','window.sisaBuku(2,3)===null&&window.sisaBuku(-1,0)===null&&window.sisaBuku(2.5,1)===null']]);
jsTask('J01','Label kode anggota','Definisikan window.labelAnggota(nama,nomor) yang menghasilkan nama.trim() + " [" + nomor + "]". Nomor dipertahankan sebagai teks termasuk nol awal.','window.labelAnggota=(nama,nomor)=>nama.trim()+\' [\'+nomor+\']\';',[
 ['Nilai string berbeda',"window.labelAnggota('Dina','A001')==='Dina [A001]'&&window.labelAnggota('Budi','B023')==='Budi [B023]'"],['Whitespace nama',"window.labelAnggota('  Sari  ','001')==='Sari [001]'"],['Nomor tidak dikonversi angka',"window.labelAnggota('Web','0007')==='Web [0007]'&&window.labelAnggota('X','AB-02')==='X [AB-02]'"]]);
const loop='(sourceFacts.js.counts.ForStatement??0)+(sourceFacts.js.counts.ForOfStatement??0)+(sourceFacts.js.counts.WhileStatement??0) > 0';
jsTask('J02','Hitung buku tersedia','Definisikan window.jumlahTersedia(data), hitung object dengan stok>0 memakai for/for-of/while dan kondisi.','window.jumlahTersedia=data=>{let n=0;for(const b of data){if(b.stok>0)n++;}return n;};',[
 ['Koleksi campuran','window.jumlahTersedia([{stok:0},{stok:2},{stok:8},{stok:-1}])===2&&window.jumlahTersedia([{stok:1}])===1'],['Koleksi kosong','window.jumlahTersedia([])===0'],['Iterasi nyata',loop]]);
jsTask('J02','Total stok valid','Definisikan window.totalStok(data): jumlahkan hanya stok integer >=0 memakai loop dan kondisi; lewati data stok yang tidak valid.','window.totalStok=data=>{let total=0;for(const b of data){if(Number.isInteger(b.stok)&&b.stok>=0)total+=b.stok;}return total;};',[
 ['Jumlah tidak konstan','window.totalStok([{stok:2},{stok:5}])===7&&window.totalStok([{stok:11}])===11'],['Invalid dan kosong',"window.totalStok([])===0&&window.totalStok([{stok:-1},{stok:'3'},{stok:1.5},{stok:0}])===0"],['Loop dipakai',loop]]);
jsTask('J02','Kategorikan keterlambatan','Definisikan window.statusPinjaman(hari,sudahKembali): "selesai" jika sudah kembali, "terlambat" jika hari>14, selainnya "aktif". Gunakan percabangan.','window.statusPinjaman=(hari,kembali)=>{if(kembali)return \'selesai\';if(hari>14)return \'terlambat\';return \'aktif\';};',[
 ['Cabang aktif/terlambat',"window.statusPinjaman(3,false)==='aktif'&&window.statusPinjaman(20,false)==='terlambat'"],['Batas empat belas hari',"window.statusPinjaman(14,false)==='aktif'&&window.statusPinjaman(15,false)==='terlambat'"],['Kembali mengungguli hari',"window.statusPinjaman(30,true)==='selesai'&&((sourceFacts.js.counts.IfStatement??0)+(sourceFacts.js.counts.ConditionalExpression??0)>0)"]]);
jsTask('J03','Pencocok berdasarkan field','Definisikan window.buatPencocok(kunci) yang mengembalikan fungsi (obj,keyword), case-insensitive pada field itu. Field hilang dianggap string kosong.','window.buatPencocok=kunci=>(obj,q)=>String(obj[kunci]??\'\').toLowerCase().includes(q.toLowerCase());',[
 ['Dua closure berbeda',"(()=>{const a=window.buatPencocok('judul'),b=window.buatPencocok('nama');return a({judul:'WEB'},'web')&&b({nama:'Dina'},'din')&&!b({judul:'Dina'},'din');})()"],['Input kosong/field hilang',"window.buatPencocok('judul')({},'x')===false&&window.buatPencocok('judul')({judul:'Web'},'')===true"],['State closure tidak tertukar',"(()=>{const a=window.buatPencocok('judul');window.buatPencocok('nama');return a({judul:'CSS'},'css');})()"]]);
jsTask('J03','Penghitung lokal peminjaman','Definisikan window.buatPenghitung(awal) yang mengembalikan fungsi tanpa argumen. Setiap pemanggilan menambah dan mengembalikan angka 1 lebih besar; instance tidak berbagi state.','window.buatPenghitung=awal=>{let n=awal;return ()=>++n;};',[
 ['State bertahan antar pemanggilan','(()=>{const f=window.buatPenghitung(2);return f()===3&&f()===4&&f()===5;})()'],['Instance terisolasi','(()=>{const a=window.buatPenghitung(0),b=window.buatPenghitung(10);return a()===1&&b()===11&&a()===2;})()'],['Awal nol/negatif','window.buatPenghitung(0)()===1&&window.buatPenghitung(-1)()===0']]);
jsTask('J03','Formatter katalog','Definisikan window.buatFormatter(prefix) yang mengembalikan fungsi (judul,stok) -> "prefix: judul (stok)". Prefix harus ditangkap oleh closure.','window.buatFormatter=prefix=>(judul,stok)=>prefix+\': \'+judul+\' (\'+stok+\')\';',[
 ['Parameter dipakai',"window.buatFormatter('Buku')('Web',2)==='Buku: Web (2)'&&window.buatFormatter('Katalog')('CSS',7)==='Katalog: CSS (7)'"],['Nol tidak hilang',"window.buatFormatter('Stok')('JS',0)==='Stok: JS (0)'"],['Closure tetap independen',"(()=>{const a=window.buatFormatter('A'),b=window.buatFormatter('B');return a('X',1)==='A: X (1)'&&b('X',1)==='B: X (1)';})()"]]);
jsTask('J04','Ringkasan JSON buku','Definisikan window.ringkasBuku(jsonText) -> {judul:string[],total:number}. Parse array object buku; JSON rusak/nonarray menghasilkan null.','window.ringkasBuku=text=>{try{const data=JSON.parse(text);if(!Array.isArray(data))return null;return {judul:data.map(b=>b.judul),total:data.reduce((s,b)=>s+b.stok,0)};}catch{return null;}};',[
 ['Object dan array diproses',"JSON.stringify(window.ringkasBuku('[{\"judul\":\"Web\",\"stok\":2},{\"judul\":\"CSS\",\"stok\":3}]'))===JSON.stringify({judul:['Web','CSS'],total:5})"],['Array kosong',"JSON.stringify(window.ringkasBuku('[]'))===JSON.stringify({judul:[],total:0})"],['JSON invalid ditangani',"window.ringkasBuku('{')===null&&window.ringkasBuku('{}')===null"]]);
jsTask('J04','Cari anggota tanpa mutasi','Definisikan window.cariAnggota(data,nomor): object anggota yang nomornya sama persis, atau null. Jangan mengubah array/objek input.','window.cariAnggota=(data,nomor)=>data.find(a=>a.no_anggota===nomor)??null;',[
 ['Identitas string dipertahankan',"window.cariAnggota([{no_anggota:'001',nama:'Dina'},{no_anggota:'1',nama:'Budi'}],'001')?.nama==='Dina'"],['Tidak ada hasil',"window.cariAnggota([],'A')===null&&window.cariAnggota([{no_anggota:'A'}],'B')===null"],['Input tidak berubah',"(()=>{const d=[{no_anggota:'B',nama:'Budi'},{no_anggota:'A',nama:'Dina'}],before=JSON.stringify(d);window.cariAnggota(d,'A');return JSON.stringify(d)===before;})()"]]);
jsTask('J04','Daftar judul tersedia','Definisikan window.judulTersedia(data): array judul dengan stok>0 dalam urutan input, tanpa memutasi data.','window.judulTersedia=data=>data.filter(b=>b.stok>0).map(b=>b.judul);',[
 ['Filter dan map',"JSON.stringify(window.judulTersedia([{judul:'A',stok:0},{judul:'B',stok:3},{judul:'C',stok:1}]))==='[\"B\",\"C\"]'"],['Tidak tersedia menghasilkan kosong',"JSON.stringify(window.judulTersedia([]))==='[]'&&JSON.stringify(window.judulTersedia([{judul:'X',stok:0}]))==='[]'"],['Tidak mengubah urutan/input',"(()=>{const d=Object.freeze([Object.freeze({judul:'Z',stok:2}),Object.freeze({judul:'A',stok:1})]);return JSON.stringify(window.judulTersedia(d))==='[\"Z\",\"A\"]';})()"]]);
jsTask('J05','Render katalog aman','Definisikan window.renderBuku(data,tbody): ganti isi tbody dengan row Judul/Stok. [] mengosongkan tbody. Judul harus teks, bukan markup.','window.renderBuku=(data,tbody)=>{tbody.replaceChildren();for(const b of data){const tr=document.createElement(\'tr\');for(const v of [b.judul,b.stok]){const td=document.createElement(\'td\');td.textContent=String(v);tr.append(td);}tbody.append(tr);}};',[
 ['Render dua row',"(()=>{const t=document.querySelector('tbody');window.renderBuku([{judul:'Web',stok:2},{judul:'CSS',stok:0}],t);return t.rows.length===2&&t.rows[1].cells[0].textContent==='CSS'&&t.rows[1].cells[1].textContent==='0';})()"],['Render ulang tidak mengganda',"(()=>{const t=document.querySelector('tbody');window.renderBuku([{judul:'JS',stok:1}],t);const ok=t.rows.length===1;window.renderBuku([],t);return ok&&t.rows.length===0;})()"],['Masukan markup tetap teks',"(()=>{const t=document.querySelector('tbody');window.renderBuku([{judul:'<img src=x onerror=alert(1)>',stok:1}],t);return !t.querySelector('img')&&t.rows[0].cells[0].textContent.includes('<img');})()"]],'<table><tbody></tbody></table>');
jsTask('J05','Render pilihan anggota','Definisikan window.renderAnggota(data,select): ganti semua option dengan value no_anggota dan teks nama; [] mengosongkan select.','window.renderAnggota=(data,select)=>{select.replaceChildren();for(const a of data){const o=document.createElement(\'option\');o.value=a.no_anggota;o.textContent=a.nama;select.append(o);}};',[
 ['Value dan label berpasangan',"(()=>{const s=document.querySelector('select');window.renderAnggota([{no_anggota:'001',nama:'Dina'},{no_anggota:'A02',nama:'Budi'}],s);return s.options.length===2&&s.options[0].value==='001'&&s.options[1].textContent==='Budi';})()"],['Penggantian pilihan',"(()=>{const s=document.querySelector('select');window.renderAnggota([{no_anggota:'X',nama:'Sari'}],s);return s.options.length===1&&s.options[0].value==='X';})()"],['Kosong dan teks aman',"(()=>{const s=document.querySelector('select');window.renderAnggota([{no_anggota:'Z',nama:'<b>X</b>'}],s);const ok=!s.querySelector('b')&&s.options[0].textContent==='<b>X</b>';window.renderAnggota([],s);return ok&&s.options.length===0;})()"]],'<select></select>');
jsTask('J05','Status ketersediaan kartu','Definisikan window.tampilkanStatus(el,stok): teks Tersedia dan class tersedia jika stok>0; selainnya teks Habis dan tanpa class tersedia. Pemanggilan ulang harus memperbarui elemen yang sama.','window.tampilkanStatus=(el,stok)=>{el.textContent=stok>0?\'Tersedia\':\'Habis\';el.classList.toggle(\'tersedia\',stok>0);};',[
 ['Stok positif',"(()=>{const e=document.querySelector('#status');window.tampilkanStatus(e,3);return e.textContent==='Tersedia'&&e.classList.contains('tersedia');})()"],['Nol menghapus status lama',"(()=>{const e=document.querySelector('#status');window.tampilkanStatus(e,0);return e.textContent==='Habis'&&!e.classList.contains('tersedia');})()"],['Elemen lain tidak berubah',"(()=>{const e=document.querySelector('#status');window.tampilkanStatus(e,1);return e.textContent==='Tersedia'&&document.querySelector('#lain').textContent==='Tetap';})()"]],'<p id="status"></p><p id="lain">Tetap</p>');
jsTask('J06','Toggle navigasi JS','Definisikan window.initMenu(button,nav). Klik men-toggle class nav-open pada nav dan aria-expanded pada tombol, awal false. Jika elemen tidak ada, jangan error.','window.initMenu=(button,nav)=>{if(!button||!nav)return;button.setAttribute(\'aria-expanded\',\'false\');button.addEventListener(\'click\',()=>{const open=nav.classList.toggle(\'nav-open\');button.setAttribute(\'aria-expanded\',String(open));});};',[
 ['Klik pertama membuka',"(()=>{window.initMenu(document.querySelector('button'),document.querySelector('nav'));document.querySelector('button').click();return document.querySelector('nav').classList.contains('nav-open')&&document.querySelector('button').getAttribute('aria-expanded')==='true';})()"],['Klik kedua menutup',"(()=>{document.querySelector('button').click();return !document.querySelector('nav').classList.contains('nav-open')&&document.querySelector('button').getAttribute('aria-expanded')==='false';})()"],['Guard halaman tanpa target',"(()=>{window.initMenu(null,null);return true;})()"]],'<button>Menu</button><nav>Buku</nav>');
jsTask('J06','Penghitung pilihan buku','Definisikan window.initCounter(button,output), mulai 0 dan setiap klik menambah 1. Dua pasangan elemen harus mempunyai counter terpisah.','window.initCounter=(b,o)=>{let n=0;o.textContent=\'0\';b.addEventListener(\'click\',()=>o.textContent=String(++n));};',[
 ['Listener merespons berulang',"(()=>{window.initCounter(document.querySelector('#a'),document.querySelector('#oa'));document.querySelector('#a').click();document.querySelector('#a').click();return document.querySelector('#oa').textContent==='2';})()"],['Pasangan kedua independen',"(()=>{window.initCounter(document.querySelector('#b'),document.querySelector('#ob'));document.querySelector('#b').click();return document.querySelector('#ob').textContent==='1'&&document.querySelector('#oa').textContent==='2';})()"],['State pertama bertahan',"(()=>{document.querySelector('#a').click();return document.querySelector('#oa').textContent==='3'&&document.querySelector('#ob').textContent==='1';})()"]],'<button id="a">Buku A</button><output id="oa"></output><button id="b">Buku B</button><output id="ob"></output>');
jsTask('J06','Perubahan kategori','Definisikan window.initKategori(select,output), pasang event change yang menampilkan value saat ini. Awalnya output menampilkan value awal.','window.initKategori=(s,o)=>{const update=()=>o.textContent=s.value;s.addEventListener(\'change\',update);update();};',[
 ['Nilai awal di-render',"(()=>{window.initKategori(document.querySelector('select'),document.querySelector('output'));return document.querySelector('output').textContent==='Web';})()"],['Change membaca nilai baru',"(()=>{const s=document.querySelector('select');s.value='Umum';s.dispatchEvent(new Event('change'));return document.querySelector('output').textContent==='Umum';})()"],['Change kedua tidak memakai nilai lama',"(()=>{const s=document.querySelector('select');s.value='Web';s.dispatchEvent(new Event('change'));return document.querySelector('output').textContent==='Web';})()"]],'<select><option value="Web">Web</option><option value="Umum">Umum</option></select><output></output>');

for(const [title,field,type,min,max] of [['Validasi judul','judul','text',0,0],['Validasi stok','stok','integer',0,9999],['Validasi tahun','tahun','integer',1900,2026]] as const){
 const valid=type==='text'?`typeof value==='string'&&value.trim().length>0`:`String(value).trim()!==''&&Number.isInteger(Number(value))&&Number(value)>=${min}&&Number(value)<=${max}`;
 jsTask('J07',title,`Definisikan window.validasi(value) -> boolean: ${type==='text'?'teks judul setelah trim wajib tidak kosong':`${field} integer ${min}-${max}, bukan string kosong`}. Definisikan window.initValidasi(form) yang memasang submit listener, membaca input name=${field}, lalu mengisi .error dengan '${field} tidak valid' saat gagal atau mengosongkannya saat valid. Batalkan submit invalid. Handler sandbox juga membatalkan navigasi; tes menilai fungsi validator dan pesan, bukan defaultPrevented.`,
 `window.validasi=value=>${valid};window.initValidasi=form=>{form.addEventListener('submit',e=>{const ok=window.validasi(form.elements.${field}.value);form.querySelector('.error').textContent=ok?'':'${field} tidak valid';if(!ok)e.preventDefault();});};`,[
 ['Kasus normal dan batas',type==='text'?"window.validasi('Web')===true&&window.validasi('  CSS  ')===true":`window.validasi('${min}')===true&&window.validasi('${max}')===true&&window.validasi('${min-1}')===false&&window.validasi('${max+1}')===false`],
 ['Input kosong/invalid',type==='text'?"window.validasi('')===false&&window.validasi('   ')===false":`window.validasi('')===false&&window.validasi('abc')===false&&window.validasi('1.5')===false`],
 ['Submit invalid lalu diperbaiki',`(()=>{const f=document.querySelector('form');window.initValidasi(f);f.elements.${field}.value='';f.dispatchEvent(new Event('submit',{cancelable:true}));const bad=f.querySelector('.error').textContent==='${field} tidak valid';f.elements.${field}.value=${JSON.stringify(type==='text'?'Web':String(min))};f.dispatchEvent(new Event('submit',{cancelable:true}));return bad&&f.querySelector('.error').textContent==='';})()`]
 ],`<form><label>${field}<input name="${field}"></label><span class="error"></span><button type="submit">Simpan</button></form>`);
}

for(const [title,selector,data] of [['Filter judul','td:first-child',[['Web Dasar','Dina'],['CSS Layout','Budi'],['WEB Lanjut','Sari']]],['Filter anggota','td:nth-child(2)',[['A001','Dina'],['A002','Budi'],['A003','DINI']]],['Filter seluruh baris','',[['HTML','Dina'],['CSS','Budi'],['JavaScript','Dina']]]] as const){
 const keyword=title==='Filter judul'?'web':title==='Filter anggota'?'din':'dina';
 const html=`<input id="cari"><table><thead><tr><th>Kolom 1</th><th>Kolom 2</th></tr></thead><tbody>${data.map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
 jsTask('J08',title,`Definisikan window.initFilter(input,table) dengan event input. Saring ${selector?'teks selector '+selector:'seluruh teks baris'} secara case-insensitive: row.hidden=true jika tidak cocok, false bila cocok. Input kosong memulihkan semua baris; header tidak disaring.`,
 `window.initFilter=(input,table)=>input.addEventListener('input',()=>{const q=input.value.toLowerCase();for(const row of table.querySelectorAll('tbody tr')){const text=${selector?`row.querySelector(${JSON.stringify(selector)}).textContent`:'row.textContent'};row.hidden=!text.toLowerCase().includes(q);}});`,[
 ['Pencocokan case-insensitive',`(()=>{const i=document.querySelector('input'),t=document.querySelector('table');window.initFilter(i,t);i.value=${JSON.stringify(keyword.toUpperCase())};i.dispatchEvent(new Event('input'));return [...t.tBodies[0].rows].filter(r=>!r.hidden).length===2;})()`],
 ['Tanpa kecocokan',"(()=>{const i=document.querySelector('input');i.value='tidak-ada';i.dispatchEvent(new Event('input'));return [...document.querySelectorAll('tbody tr')].every(r=>r.hidden)&&!document.querySelector('thead tr').hidden;})()"],
 ['Input kosong memulihkan semua',"(()=>{const i=document.querySelector('input');i.value='';i.dispatchEvent(new Event('input'));return [...document.querySelectorAll('tbody tr')].every(r=>!r.hidden);})()"]],html);
}

for(const [title,action] of [['Hapus baris dinamis','remove'],['Tandai pilihan dinamis','toggle'],['Konfirmasi arsip dinamis','archive']] as const){
 const effect=action==='remove'?'row.remove()':action==='toggle'?"row.classList.toggle('dipilih')":"row.dataset.status='arsip'";
 const assertAfter=action==='remove'?"!root.contains(row)":action==='toggle'?"row.classList.contains('dipilih')":"row.dataset.status==='arsip'";
 jsTask('J09',title,`Definisikan window.initDelegasi(root,confirmer): satu listener click pada root untuk button[data-action=aksi] termasuk klik span anak. Panggil confirmer(teks sel pertama). Jika true, ${action==='remove'?'hapus tr':action==='toggle'?'toggle class dipilih pada tr':'ubah data-status tr menjadi arsip'}. Jika false/klik di luar target, abaikan. Baris bisa ditambah sesudah init.`,
 `window.initDelegasi=(root,confirmer)=>root.addEventListener('click',e=>{const b=e.target.closest('button[data-action=aksi]');if(!b||!root.contains(b))return;const row=b.closest('tr');if(row&&confirmer(row.cells[0].textContent)){${effect};}});`,[
 ['Baris baru dan target anak',`(()=>{const root=document.querySelector('tbody');let called='';window.initDelegasi(root,text=>{called=text;return true;});root.insertAdjacentHTML('beforeend','<tr><td>Web</td><td><button data-action="aksi"><span>Proses</span></button></td></tr>');const row=root.lastElementChild;row.querySelector('span').click();return called==='Web'&&${assertAfter};})()`],
 ['Penolakan tidak memutasi',"(()=>{const t=document.createElement('tbody');t.innerHTML='<tr><td>CSS</td><td><button data-action=aksi>Proses</button></td></tr>';document.querySelector('table').append(t);window.initDelegasi(t,()=>false);const before=t.innerHTML;t.querySelector('button').click();return t.innerHTML===before;})()"],
 ['Klik nonaksi diabaikan',"(()=>{const t=document.createElement('tbody');t.innerHTML='<tr><td>JS</td><td><button>Detail</button></td></tr>';document.querySelector('table').append(t);let n=0;window.initDelegasi(t,()=>{n++;return true;});t.querySelector('button').click();return n===0&&t.rows.length===1;})()"]],'<table><tbody></tbody></table>');
}

jsTask('J10','Ambil katalog JSON','Definisikan async window.ambilBuku(fetcher,url). Await response, tolak jika !ok, await json(), pastikan array dan kembalikan array. Error harus menjadi rejection. Fetcher disuntikkan test; jaringan nyata diblokir.','window.ambilBuku=async(fetcher,url)=>{const r=await fetcher(url);if(!r.ok)throw Error(\'HTTP\');const d=await r.json();if(!Array.isArray(d))throw Error(\'Array\');return d;};',[
 ['Await respons dan JSON',"(await window.ambilBuku(async url=>({ok:true,json:async()=>[{judul:url}]}),'/buku'))[0].judul==='/buku'"],['HTTP error ditolak',"await(async()=>{try{await window.ambilBuku(async()=>({ok:false,json:async()=>[]}),'/x');return false;}catch{return true;}})()"],['Network/JSON/bentuk invalid ditolak',"await(async()=>{for(const f of [async()=>{throw Error('network')},async()=>({ok:true,json:async()=>{throw Error('json')}}),async()=>({ok:true,json:async()=>({})})]){try{await window.ambilBuku(f,'/x');return false;}catch{}}return true;})()"]]);
jsTask('J10','Jumlah anggota dari API','Definisikan async window.jumlahAnggota(fetcher,url): ambil array JSON, tolak respons !ok/nonarray, kembalikan panjang array.','window.jumlahAnggota=async(f,u)=>{const r=await f(u);if(!r.ok)throw Error(\'HTTP\');const a=await r.json();if(!Array.isArray(a))throw Error(\'Array\');return a.length;};',[
 ['Jumlah bervariasi',"(await window.jumlahAnggota(async u=>({ok:true,json:async()=>u==='/anggota'?[1,2,3]:[1]}),'/anggota'))===3"],['Array kosong sah',"(await window.jumlahAnggota(async()=>({ok:true,json:async()=>[]}),'/empty'))===0"],['Status dan bentuk salah',"await(async()=>{for(const r of [{ok:false,json:async()=>[]},{ok:true,json:async()=>null}]){try{await window.jumlahAnggota(async()=>r,'/');return false;}catch{}}return true;})()"]]);
jsTask('J10','Urutan detail peminjaman','Definisikan async window.ambilJudulPinjaman(fetcher,id). Fetch /pinjaman/id -> JSON {buku_id}; lalu fetch /buku/buku_id -> JSON {judul}, return judul. Tolak setiap response !ok.','window.ambilJudulPinjaman=async(f,id)=>{const a=await f(\'/pinjaman/\'+id);if(!a.ok)throw Error(\'HTTP\');const p=await a.json();const b=await f(\'/buku/\'+p.buku_id);if(!b.ok)throw Error(\'HTTP\');return (await b.json()).judul;};',[
 ['Request kedua menunggu ID pertama',"await(async()=>{const urls=[];const v=await window.ambilJudulPinjaman(async u=>{urls.push(u);return {ok:true,json:async()=>u==='/pinjaman/7'?{buku_id:23}:{judul:'Web'}};},7);return v==='Web'&&JSON.stringify(urls)==='[\"/pinjaman/7\",\"/buku/23\"]';})()"],['Error tahap pertama menghentikan rantai',"await(async()=>{let n=0;try{await window.ambilJudulPinjaman(async()=>{n++;return {ok:false};},1);return false;}catch{return n===1;}})()"],['Error tahap kedua ditolak',"await(async()=>{try{await window.ambilJudulPinjaman(async u=>u.startsWith('/pinjaman')?{ok:true,json:async()=>({buku_id:2})}:{ok:false},1);return false;}catch{return true;}})()"]]);

for(const [title,field] of [['Muat ulang katalog','judul']] as const){
 jsTask('J11',title,`Definisikan window.setupPemuatan(root,fetcher). Pasang listener tombol .retry yang setiap klik mengambil '/data', menampilkan .loading selama Promise tertunda, memeriksa response.ok, membaca array JSON dan menampilkan field ${field} tiap item pada satu li di .hasil. Pada error tampilkan 'Gagal memuat data' di .error; finally sembunyikan loading. Retry menghapus error dan mengganti hasil. Fungsi init tidak langsung memuat.`,
 `window.setupPemuatan=(root,fetcher)=>{root.querySelector('.loading').hidden=true;root.querySelector('.retry').addEventListener('click',async()=>{const loading=root.querySelector('.loading'),err=root.querySelector('.error'),list=root.querySelector('.hasil');loading.hidden=false;err.textContent='';list.replaceChildren();try{const r=await fetcher('/data');if(!r.ok)throw Error('HTTP');const data=await r.json();if(!Array.isArray(data))throw Error('Array');for(const item of data){const li=document.createElement('li');li.textContent=item.${field};list.append(li);}}catch{err.textContent='Gagal memuat data';}finally{loading.hidden=true;}});};`,[
 ['Loading terlihat selama Promise tertunda',`await(async()=>{const r=document.querySelector('.root');let resolve;window.__pending=new Promise(done=>resolve=done);window.__resolve=resolve;window.setupPemuatan(r,()=>window.__pending);r.querySelector('.retry').click();return !r.querySelector('.loading').hidden;})()`],
 ['Sukses menutup loading dan merender',`await(async()=>{window.__resolve({ok:true,json:async()=>[{${field}:'Web'},{${field}:'CSS'}]});await new Promise(r=>setTimeout(r,20));const root=document.querySelector('.root');return root.querySelector('.loading').hidden&&JSON.stringify([...root.querySelectorAll('li')].map(n=>n.textContent))==='["Web","CSS"]'&&root.querySelector('.error').textContent==='';})()`],
 ['Error lalu retry berhasil',`await(async()=>{const r=document.querySelector('.root').cloneNode(true);document.body.append(r);let n=0;window.setupPemuatan(r,async()=>{if(n++===0)throw Error('network');return {ok:true,json:async()=>[{${field}:'Pulih'}]};});r.querySelector('.retry').click();await new Promise(r=>setTimeout(r,20));const bad=r.querySelector('.loading').hidden&&r.querySelector('.error').textContent==='Gagal memuat data';r.querySelector('.retry').click();await new Promise(r=>setTimeout(r,20));return bad&&r.querySelector('.loading').hidden&&r.querySelector('.error').textContent===''&&r.querySelectorAll('li').length===1&&r.querySelector('li').textContent==='Pulih';})()`],
 ['HTTP gagal juga menutup loading',"await(async()=>{const r=document.querySelector('.root').cloneNode(true);document.body.append(r);window.setupPemuatan(r,async()=>({ok:false}));r.querySelector('.retry').click();await new Promise(r=>setTimeout(r,20));return r.querySelector('.loading').hidden&&r.querySelector('.error').textContent==='Gagal memuat data';})()"]
 ],'<section class="root"><button class="retry">Muat ulang</button><p class="loading" hidden>Memuat</p><p class="error"></p><ul class="hasil"></ul></section>');
}

jsTask('J11','Pilihan anggota tahan gangguan','Definisikan window.setupPilihan(root,fetcher). Klik .retry mengambil /anggota, disable tombol selama request, cek ok dan array JSON {id,nama}, lalu ganti option select (value=id, teks=nama). Jika gagal, tampilkan Gagal memuat anggota pada .error dan pertahankan pilihan lama. Retry sukses menghapus error. Tombol harus aktif kembali pada semua jalur.',
 "window.setupPilihan=(r,f)=>{const b=r.querySelector('.retry'),s=r.querySelector('select'),e=r.querySelector('.error');b.addEventListener('click',async()=>{b.disabled=true;e.textContent='';try{const response=await f('/anggota');if(!response.ok)throw Error('HTTP');const d=await response.json();if(!Array.isArray(d))throw Error('Array');s.replaceChildren();for(const a of d){const o=document.createElement('option');o.value=a.id;o.textContent=a.nama;s.append(o);}}catch{e.textContent='Gagal memuat anggota';}finally{b.disabled=false;}});};",[
 ['Tombol terkunci saat menunggu',"(()=>{const r=document.querySelector('.root');let done;const pending=new Promise(resolve=>done=resolve);window.__pilihanDone=done;window.setupPilihan(r,()=>pending);r.querySelector('.retry').click();return r.querySelector('.retry').disabled;})()"],
 ['Pilihan berasal dari data',"await(async()=>{window.__pilihanDone({ok:true,json:async()=>[{id:'A001',nama:'Dina'}]});await new Promise(r=>setTimeout(r,20));const r=document.querySelector('.root'),s=r.querySelector('select');return !r.querySelector('.retry').disabled&&s.options.length===1&&s.options[0].value==='A001'&&s.options[0].textContent==='Dina';})()"],
 ['Gagal mempertahankan data lalu retry menggantinya',"await(async()=>{const r=document.querySelector('.root').cloneNode(true);document.body.append(r);let n=0;window.setupPilihan(r,async()=>{if(n++===0)throw Error('network');return {ok:true,json:async()=>[{id:'B002',nama:'Budi'}]};});r.querySelector('.retry').click();await new Promise(r=>setTimeout(r,20));const bad=r.querySelector('.error').textContent==='Gagal memuat anggota'&&r.querySelector('select').value==='A001'&&!r.querySelector('.retry').disabled;r.querySelector('.retry').click();await new Promise(r=>setTimeout(r,20));return bad&&r.querySelector('.error').textContent===''&&r.querySelectorAll('option').length===1&&r.querySelector('select').value==='B002';})()"],
 ['HTTP/JSON gagal juga memulihkan kontrol',"await(async()=>{for(const response of [{ok:false},{ok:true,json:async()=>{throw Error('JSON')}}]){const r=document.querySelector('.root').cloneNode(true);document.body.append(r);window.setupPilihan(r,async()=>response);r.querySelector('.retry').click();await new Promise(r=>setTimeout(r,20));if(r.querySelector('.retry').disabled||r.querySelector('.error').textContent!=='Gagal memuat anggota')return false;}return true;})()"]
 ],'<section class="root"><button class="retry">Muat anggota</button><p class="error"></p><select><option value="lama">Data lama</option></select></section>');
jsTask('J11','Statistik dengan nilai terakhir','Definisikan window.setupStat(root,fetcher). Klik .retry mengambil /statistik, JSON {total} integer >=0. Saat menunggu, .status=Memuat dan tombol disabled. Sukses: perbarui .count dan status Siap. Gagal: status Gagal tanpa menghapus angka terakhir. Retry menerima total=0. Semua jalur mengaktifkan tombol kembali.',
 "window.setupStat=(r,f)=>{const b=r.querySelector('.retry'),s=r.querySelector('.status'),c=r.querySelector('.count');b.addEventListener('click',async()=>{s.textContent='Memuat';b.disabled=true;try{const response=await f('/statistik');if(!response.ok)throw Error('HTTP');const d=await response.json();if(!Number.isInteger(d.total)||d.total<0)throw Error('Total');c.textContent=String(d.total);s.textContent='Siap';}catch{s.textContent='Gagal';}finally{b.disabled=false;}});};",[
 ['State menunggu dapat diamati',"(()=>{const r=document.querySelector('.root');let done;window.setupStat(r,()=>new Promise(resolve=>done=resolve));r.querySelector('.retry').click();window.__statDone=done;return r.querySelector('.status').textContent==='Memuat'&&r.querySelector('.retry').disabled;})()"],
 ['Sukses memperbarui angka',"await(async()=>{window.__statDone({ok:true,json:async()=>({total:7})});await new Promise(r=>setTimeout(r,20));const r=document.querySelector('.root');return r.querySelector('.status').textContent==='Siap'&&r.querySelector('.count').textContent==='7'&&!r.querySelector('.retry').disabled;})()"],
 ['Nilai terakhir bertahan saat gagal dan nol diterima',"await(async()=>{const r=document.querySelector('.root').cloneNode(true);document.body.append(r);let n=0;window.setupStat(r,async()=>{if(n++===0)throw Error('network');return {ok:true,json:async()=>({total:0})};});r.querySelector('.retry').click();await new Promise(r=>setTimeout(r,20));const bad=r.querySelector('.status').textContent==='Gagal'&&r.querySelector('.count').textContent==='7';r.querySelector('.retry').click();await new Promise(r=>setTimeout(r,20));return bad&&r.querySelector('.count').textContent==='0'&&r.querySelector('.status').textContent==='Siap'&&!r.querySelector('.retry').disabled;})()"],
 ['Total invalid tidak merusak data sebelumnya',"await(async()=>{for(const total of [-1,1.5,'2']){const r=document.querySelector('.root').cloneNode(true);document.body.append(r);window.setupStat(r,async()=>({ok:true,json:async()=>({total})}));r.querySelector('.retry').click();await new Promise(r=>setTimeout(r,20));if(r.querySelector('.status').textContent!=='Gagal'||r.querySelector('.count').textContent!=='7'||r.querySelector('.retry').disabled)return false;}return true;})()"]
 ],'<section class="root"><button class="retry">Muat statistik</button><output class="count">0</output><p class="status">Idle</p></section>');

export const curriculumExercises:Exercise[]=specs.map((s,index)=>{
 const node=curriculumKCs.find(k=>k.id===s.kc)!;
 const variant=specs.slice(0,index).filter(x=>x.kc===s.kc).length+1;
 const staticTask=s.kc.startsWith('H')||s.kc.startsWith('C');
 const tests=[...s.tests];
 if(node.assessment_ready&&staticTask)tests.push(["HTML/CSS dikerjakan tanpa JavaScript","sourceFacts.js.statements===0 && !sourceFacts.js.syntaxError"]);
 return {id:`simpus-${s.kc.toLowerCase()}-${variant}-v1`,title:s.title,instructions:s.instruction,
 starter_code:{html:s.starter?.html??'',css:s.starter?.css??'',js:s.starter?.js??''},
 // Existing authoring scale from the proposal, not a new BKT/CPT parameter.
 difficulty:[0.3,0.5,0.7][variant-1],
 hints:s.hints??["Konsep "+node.code+": "+node.description,"Pada tugas "+s.title+", cocokkan struktur parent/child dan atribut dengan kontrak soal; jangan hanya menyalin teks yang terlihat.","Contoh parsial: "+(s.solution.html??s.solution.css??s.solution.js??"").slice(0,100)],
 kcs:[{id:s.kc,weight:1}],tests:tests.map(([description,script],i)=>({id:`simpus-${s.kc.toLowerCase()}-${variant}-t${i+1}`,description,script,timeout_ms:1500})),
 curriculum_version:CURRICULUM_VERSION,evaluator:s.kc==='H01'?'source':s.kc==='J10'||s.kc.startsWith('J')&&Number(s.kc.slice(1))<=4?'js':'dom',
 assessment_ready:node.assessment_ready,assessment_note:node.assessment_note,sources:node.sources,
 };
});
/** Reference solutions are used by offline verification only, never imported by pages/APIs. */
export const curriculumSolutions=Object.fromEntries(curriculumExercises.map((e,i)=>[e.id,{...e.starter_code,...specs[i].solution}]));
